def load_dynamic_tokens() -> list[str]:
    """Load extra bot tokens from bot_tokens.json."""
    if TOKENS_FILE.exists():
        try:
            data = json.loads(TOKENS_FILE.read_text(encoding="utf-8"))
            if isinstance(data, list):
                return [t for t in data if isinstance(t, str) and t.strip()]
        except Exception:
            pass
    return []


def save_dynamic_tokens(tokens: list[str]) -> None:
    """Save extra bot tokens to bot_tokens.json."""
    TOKENS_FILE.write_text(json.dumps(tokens, indent=2), encoding="utf-8")


def load_known_chats() -> set[int]:
    """Load previously known group chat IDs."""
    if KNOWN_CHATS_FILE.exists():
        try:
            data = json.loads(KNOWN_CHATS_FILE.read_text(encoding="utf-8"))
            if isinstance(data, list):
                return set(int(c) for c in data)
        except Exception:
            pass
    return set()


def save_known_chats(chats: set[int]) -> None:
    """Persist known group chat IDs."""
    try:
        KNOWN_CHATS_FILE.write_text(json.dumps(list(chats), indent=2), encoding="utf-8")
    except Exception:
        pass


def load_muted_users() -> dict:
    """Load muted users {chat_id: set[uid]} from muted_users.json."""
    if MUTED_FILE.exists():
        try:
            data = json.loads(MUTED_FILE.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                return {int(k): set(int(u) for u in v) for k, v in data.items()}
        except Exception:
            pass
    return {}


def save_muted_users(muted: dict) -> None:
    """Persist muted users dict to disk."""
    try:
        MUTED_FILE.write_text(
            json.dumps({str(k): list(v) for k, v in muted.items()}, indent=2),
            encoding="utf-8",
        )
    except Exception:
        pass


def load_global_muted_users() -> set[int]:
    """Load globally muted user IDs."""
    if GLOBAL_MUTED_FILE.exists():
        try:
            data = json.loads(GLOBAL_MUTED_FILE.read_text(encoding="utf-8"))
            if isinstance(data, list):
                return {int(uid) for uid in data}
        except Exception:
            pass
    return set()


def save_global_muted_users(users: set[int]) -> None:
    try:
        GLOBAL_MUTED_FILE.write_text(json.dumps(sorted(users), indent=2), encoding="utf-8")
    except Exception:
        pass


