def load_feature_state() -> dict[str, Any]:
    """Load additive moderation/owner feature state.

    This is separate from the older config.json so existing installations keep
    all of their previous settings and old state files remain compatible.
    """
    defaults: dict[str, Any] = {
        "autopin_chats": [],
        "locked_chats": [],
        "mute_expiries": {},
        "global_mute_expiries": {},
        "bot_description_loop": {},
    }
    if FEATURES_FILE.exists():
        try:
            saved = json.loads(FEATURES_FILE.read_text(encoding="utf-8"))
            if isinstance(saved, dict):
                defaults.update(saved)
        except Exception:
            pass
    return defaults


