# ═══════════════════════════════════════════════════════════
#   HELPERS
# ═══════════════════════════════════════════════════════════

def is_auth(uid: int) -> bool:
    return uid == OWNER_ID or uid in sudo_users


def pool() -> list[Bot]:
    return [b for b in bots if b]


def arg(update: Update) -> str:
    txt   = update.message.text or ""
    parts = txt.split(None, 1)
    return parts[1].strip() if len(parts) > 1 else ""


def pick_bot(counter: list) -> Optional[Bot]:
    p = pool()
    if not p:
        return None
    b = p[counter[0] % len(p)]
    counter[0] += 1
    return b


async def _pin_message(cid: int, message_id: int, bot: Optional[Bot] = None) -> bool:
    """Pin a message when ~autopin is enabled for the chat."""
    if cid not in autopin_chats:
        return False
    candidates = [bot] if bot else []
    candidates += [b for b in pool() if b is not bot]
    for candidate in candidates:
        if not candidate:
            continue
        try:
            await candidate.pin_chat_message(
                cid, message_id, disable_notification=True
            )
            return True
        except TelegramError:
            continue
    return False


async def _send_bot_message(bot: Bot, cid: int, text: str, **kwargs):
    """Send a managed-bot message and pin it immediately when requested."""
    message = await bot.send_message(cid, text, **kwargs)
    await _pin_message(cid, message.message_id, bot)
    return message


async def _http_get_json(url: str) -> Any:
    def _get() -> Any:
        req = urllib.request.Request(
            url,
            headers={"User-Agent": "sotfy-telegram-bot/1.0"},
        )
        with urllib.request.urlopen(req, timeout=25) as response:
            return json.loads(response.read().decode("utf-8"))

    return await asyncio.to_thread(_get)


async def _run_yt_dlp(source: str) -> tuple[Optional[Path], str]:
    """Download one audio result via yt-dlp without blocking the update loop."""
    executable = shutil.which("yt-dlp")
    if not executable:
        try:
            import yt_dlp  # noqa: F401
            executable = "python"
            command_prefix = ["-m", "yt_dlp"]
        except ImportError:
            return None, "yt-dlp installed nahi hai. `pip install yt-dlp` aur ffmpeg install karo."
    else:
        command_prefix = []

    temp_dir = Path(tempfile.mkdtemp(prefix="sotfy_music_"))
    output_template = str(temp_dir / "%(title).80s.%(ext)s")
    command = [
        executable,
        *command_prefix,
        "--no-playlist",
        "--quiet",
        "--no-warnings",
        "--restrict-filenames",
        "-x",
        "--audio-format",
        "mp3",
        "-o",
        output_template,
        source,
    ]

    def _download() -> tuple[Optional[Path], str]:
        try:
            result = subprocess.run(
                command,
                capture_output=True,
                text=True,
                timeout=120,
            )
            if result.returncode != 0:
                return None, (result.stderr or result.stdout or "audio download failed")[-500:]
            files = list(temp_dir.glob("*"))
            audio = next(
                (p for p in files if p.suffix.lower() in {".mp3", ".m4a", ".opus", ".webm"}),
                None,
            )
            return audio, "" if audio else "audio file nahi mila"
        except Exception as exc:
            return None, str(exc)

    return await asyncio.to_thread(_download)


async def _search_music(query: str, limit: int = 5) -> tuple[list[dict[str, str]], str]:
    """Return lightweight YouTube search results for .search/.play <number>."""
    executable = shutil.which("yt-dlp")
    if not executable:
        try:
            import yt_dlp  # noqa: F401
            executable = "python"
            command_prefix = ["-m", "yt_dlp"]
        except ImportError:
            return [], "yt-dlp installed nahi hai. `pip install yt-dlp` karo."

    command = [
        executable,
        *command_prefix,
        "--flat-playlist",
        "--no-warnings",
        "--quiet",
        "--print",
        "%(title)s\t%(webpage_url)s",
        f"ytsearch{max(1, min(limit, 10))}:{query}",
    ]

    def _search() -> tuple[list[dict[str, str]], str]:
        try:
            result = subprocess.run(
                command, capture_output=True, text=True, timeout=45
            )
            if result.returncode != 0:
                return [], (result.stderr or result.stdout or "search failed")[-500:]
            tracks = []
            for line in result.stdout.splitlines():
                title, separator, url = line.partition("\t")
                if separator and title.strip() and url.strip():
                    tracks.append({"title": title.strip(), "url": url.strip()})
            return tracks, ""
        except Exception as exc:
            return [], str(exc)

    return await asyncio.to_thread(_search)


def _cleanup_music_file(path: Optional[Path]) -> None:
    if not path:
        return
    try:
        shutil.rmtree(path.parent, ignore_errors=True)
    except Exception:
        pass


async def _resolve_spotify_query(value: str) -> str:
    if "spotify.com" not in value:
        return value
    try:
        data = await _http_get_json(
            "https://open.spotify.com/oembed?url="
            + urllib.parse.quote(value, safe="")
        )
        title = str(data.get("title") or "").strip()
        author = str(data.get("author_name") or "").strip()
        if title:
            return f"{title} {author}".strip()
    except Exception:
        pass
    return value


async def _send_music(update: Update, mode: str) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    query = arg(update)
    if not query:
        await update.message.reply_text(
            f"Usage: `~{mode} [song name or link]`", parse_mode="Markdown"
        )
        return

    if mode == "spotify":
        query = await _resolve_spotify_query(query)
        source = query if query.startswith(("http://", "https://")) else f"ytsearch1:{query}"
    else:
        source = f"scsearch1:{query}"

    progress = await update.message.reply_text(
        f"🎵 Searching: `{query[:150]}`", parse_mode="Markdown"
    )
    audio_path, error = await _run_yt_dlp(source)
    if not audio_path:
        await progress.edit_text(
            f"❌ Music download failed:\n`{error[:700]}`", parse_mode="Markdown"
        )
        return

    try:
        with audio_path.open("rb") as audio:
            sent = await update.message.reply_audio(
                audio=audio,
                title=audio_path.stem[:128],
                performer="sotfy music",
                caption=f"🎵 {audio_path.stem}",
            )
        await _pin_message(update.effective_chat.id, sent.message_id)
        await progress.delete()
    except Exception as exc:
        await progress.edit_text(
            f"❌ Audio send failed: `{str(exc)[:500]}`", parse_mode="Markdown"
        )
    finally:
        _cleanup_music_file(audio_path)


async def cmd_dot_search(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    query = arg(update)
    if not query:
        await update.message.reply_text("Usage: `.search <song>`", parse_mode="Markdown")
        return
    results, error = await _search_music(query, 5)
    if not results:
        await update.message.reply_text(f"❌ Search failed: `{error[:500]}`", parse_mode="Markdown")
        return
    music_search_results[update.effective_chat.id] = results
    lines = ["🔍 *TOP 5 TRACKS*", ""]
    for index, track in enumerate(results, 1):
        lines.append(f"`{index}.` {track['title'][:150]}")
    lines += ["", "Play with `.play 1` to `.play 5`."]
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def _play_chat_track(update: Update, track: dict[str, str]) -> None:
    if not update.message:
        return
    cid = update.effective_chat.id
    music_current[cid] = track
    progress = await update.message.reply_text(
        f"🎧 Preparing: `{track['title'][:150]}`", parse_mode="Markdown"
    )
    path, error = await _run_yt_dlp(track["url"])
    if not path:
        await progress.edit_text(
            f"❌ Playback download failed:\n`{error[:600]}`", parse_mode="Markdown"
        )
        music_current.pop(cid, None)
        return
    try:
        with path.open("rb") as audio:
            await update.message.reply_audio(
                audio=audio,
                title=track["title"][:128],
                performer="sotfy music",
                caption=f"🎧 {track['title'][:900]}",
            )
        await progress.delete()
    except Exception as exc:
        await progress.edit_text(
            f"❌ Playback failed: `{str(exc)[:500]}`", parse_mode="Markdown"
        )
    finally:
        _cleanup_music_file(path)


async def cmd_dot_play(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    raw = arg(update).strip()
    cid = update.effective_chat.id
    reply = update.message.reply_to_message

    if reply and (reply.audio or reply.voice or reply.video):
        if reply.audio:
            track = {"title": reply.audio.title or "Telegram audio", "url": reply.audio.file_id}
            await update.message.reply_audio(audio=reply.audio.file_id, caption="🎧 Replayed Telegram audio")
        elif reply.voice:
            track = {"title": "Telegram voice", "url": reply.voice.file_id}
            await update.message.reply_voice(voice=reply.voice.file_id)
        else:
            track = {"title": "Telegram video", "url": reply.video.file_id}
            await update.message.reply_video(video=reply.video.file_id, caption="🎧 Replayed Telegram video")
        music_current[cid] = track
        return

    if not raw:
        await update.message.reply_text("Usage: `.play <song/url>` or reply to audio/video", parse_mode="Markdown")
        return

    if raw.isdigit() and cid in music_search_results:
        index = int(raw) - 1
        results = music_search_results[cid]
        if index < 0 or index >= len(results):
            await update.message.reply_text("❌ Search result number 1-5 ke beech do.")
            return
        track = results[index]
    else:
        if raw.startswith(("http://", "https://")):
            track = {"title": raw.rsplit("/", 1)[-1][:150] or "URL track", "url": raw}
        else:
            results, error = await _search_music(raw, 1)
            if not results:
                await update.message.reply_text(f"❌ Track nahi mila: `{error[:500]}`", parse_mode="Markdown")
                return
            track = results[0]

    music_queues.setdefault(cid, []).append(track)
    if cid in music_current:
        await update.message.reply_text(
            f"➕ Queue mein add: `{track['title'][:150]}`", parse_mode="Markdown"
        )
        return
    await _play_chat_track(update, music_queues[cid].pop(0))


async def cmd_dot_skip(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    cid = update.effective_chat.id
    music_current.pop(cid, None)
    queue = music_queues.get(cid, [])
    if queue:
        await _play_chat_track(update, queue.pop(0))
    else:
        await update.message.reply_text("⏭️ Current track clear. Queue empty.")


async def cmd_dot_nowplaying(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    track = music_current.get(update.effective_chat.id)
    await update.message.reply_text(
        f"🎧 Now playing: `{track['title'][:300]}`" if track else "🎧 Kuch play nahi ho raha.",
        parse_mode="Markdown",
    )


async def cmd_dot_queue(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    cid = update.effective_chat.id
    lines = ["📜 *MUSIC QUEUE*", ""]
    current = music_current.get(cid)
    if current:
        lines.append(f"▶️ Current: `{current['title'][:150]}`")
    for index, track in enumerate(music_queues.get(cid, []), 1):
        lines.append(f"{index}. `{track['title'][:150]}`")
    if len(lines) == 2:
        lines.append("Queue empty.")
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def cmd_dot_clearqueue(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    music_queues.pop(update.effective_chat.id, None)
    await update.message.reply_text("🗑️ Queue clear ho gayi. Current track unchanged.")


async def cmd_dot_autoplay(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    cid = update.effective_chat.id
    if cid in music_autoplay_chats:
        music_autoplay_chats.discard(cid)
        status = "OFF"
    else:
        music_autoplay_chats.add(cid)
        status = "ON"
    await update.message.reply_text(f"📻 Autoplay `{status}`. Chat playback ke liye enabled.", parse_mode="Markdown")


async def cmd_dot_loud(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    value = arg(update).strip()
    try:
        volume = max(0, min(200, int(value)))
    except ValueError:
        await update.message.reply_text("Usage: `.loud <0-200>`", parse_mode="Markdown")
        return
    music_settings.setdefault(update.effective_chat.id, {})["volume"] = volume
    await update.message.reply_text(f"🔊 Volume setting `{volume}dB` saved for the next playback.")


async def cmd_dot_speed(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    try:
        speed = float(arg(update))
        if speed <= 0 or speed > 4:
            raise ValueError
    except ValueError:
        await update.message.reply_text("Usage: `.speed <x>` — example `.speed 1.5`", parse_mode="Markdown")
        return
    music_settings.setdefault(update.effective_chat.id, {})["speed"] = speed
    await update.message.reply_text(f"⚡ Speed setting `{speed}x` saved for the next playback.")


async def cmd_vc_status(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    await update.message.reply_text(
        "🎙️ VC status: Bot API mode active.\n"
        "Real voice-chat join/stream ke liye Pyrogram + PyTgCalls user-session layer configure karni hogi.\n"
        "Chat audio commands `.play`, `.search`, `.queue` available hain."
    )


async def cmd_vc_unavailable(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    await update.message.reply_text(
        "⚠️ Real VC playback is not available in this Bot API-only script. "
        "Pyrogram + PyTgCalls integration is required; current `.play` sends audio in chat."
    )


async def cmd_cookies(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    await update.message.reply_text(
        "🍪 Cookies chat mein paste mat karo. Host par `cookies.txt` file/secret mount karke "
        "yt-dlp command mein `--cookies` add karna hoga."
    )


async def cmd_saverd(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    reply = update.message.reply_to_message
    parts = arg(update).split()
    if not reply or not parts or not (reply.audio or reply.voice):
        await update.message.reply_text("Audio/voice par reply karke `.saverd <name> [count]` bhejo.", parse_mode="Markdown")
        return
    name = parts[0].lower()
    try:
        count = max(1, min(int(parts[1], 10), 100)) if len(parts) > 1 else 1
    except ValueError:
        count = 1
    item = {
        "file_id": reply.audio.file_id if reply.audio else reply.voice.file_id,
        "type": "audio" if reply.audio else "voice",
        "title": (reply.audio.title if reply.audio else "voice") or "voice",
    }
    saved_rd.setdefault(name, []).extend([item.copy() for _ in range(count)])
    save_saved_rd(saved_rd)
    await update.message.reply_text(f"📥 RD `{name}` mein `{count}` file(s) save ho gayi.", parse_mode="Markdown")


async def cmd_rds(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    if not saved_rd:
        await update.message.reply_text("📁 Koi saved RD nahi hai.")
        return
    lines = ["📁 *SAVED RD LIST*", ""]
    lines += [f"• `{name}` — {len(items)} file(s)" for name, items in sorted(saved_rd.items())]
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def cmd_viewrd(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    name = arg(update).strip().lower()
    items = saved_rd.get(name)
    if not items:
        await update.message.reply_text("❌ RD nahi mila. `.rds` se list dekho.", parse_mode="Markdown")
        return
    await update.message.reply_text(
        f"🔍 RD `{name}` mein `{len(items)}` saved audio/voice files hain.",
        parse_mode="Markdown",
    )


async def cmd_delrd(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    name = arg(update).strip().lower()
    if saved_rd.pop(name, None) is None:
        await update.message.reply_text("❌ RD nahi mila.")
        return
    save_saved_rd(saved_rd)
    await update.message.reply_text(f"🗑️ RD `{name}` delete ho gaya.", parse_mode="Markdown")


async def cmd_playrd(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    parts = arg(update).split()
    if not parts or parts[0].lower() not in saved_rd:
        await update.message.reply_text("Usage: `.playrd <name> [loop]`", parse_mode="Markdown")
        return
    name = parts[0].lower()
    loop = len(parts) > 1 and parts[1].lower() == "loop"
    if update.effective_chat.id in rd_tasks:
        rd_tasks[update.effective_chat.id].cancel()

    async def _send_rd():
        try:
            while True:
                for item in saved_rd.get(name, []):
                    if item["type"] == "voice":
                        await update.message.reply_voice(voice=item["file_id"])
                    else:
                        await update.message.reply_audio(audio=item["file_id"], title=item.get("title"))
                if not loop:
                    break
                await asyncio.sleep(1)
        except asyncio.CancelledError:
            raise

    rd_tasks[update.effective_chat.id] = asyncio.create_task(_send_rd())
    await update.message.reply_text(f"▶️ RD `{name}` playback started.", parse_mode="Markdown")


async def cmd_stoprd(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    task = rd_tasks.pop(update.effective_chat.id, None)
    if task and not task.done():
        task.cancel()
    await update.message.reply_text("🛑 RD playback stopped.")


async def _set_all_bot_profile(method_name: str, **kwargs) -> tuple[int, int, str]:
    success = 0
    failed = 0
    last_error = ""
    for bot in pool():
        method = getattr(bot, method_name, None)
        if not method:
            failed += 1
            last_error = f"installed python-telegram-bot lacks {method_name}"
            continue
        try:
            await method(**kwargs)
            success += 1
        except Exception as exc:
            failed += 1
            last_error = str(exc)
    return success, failed, last_error


async def _bot_description_loop_worker(interval: int, descriptions: list[str]) -> None:
    index = 0
    try:
        while True:
            await _set_all_bot_profile(
                "set_my_description",
                description=descriptions[index % len(descriptions)],
            )
            index += 1
            await asyncio.sleep(interval)
    except asyncio.CancelledError:
        raise




async def try_rename(cid: int, name: str) -> bool:
    for b in pool():
        try:
            await b.set_chat_title(cid, name)
            return True
        except TelegramError:
            pass
    return False


async def try_send_photo(cid: int, fid: str, caption: str = "") -> bool:
    for b in pool():
        try:
            message = await b.send_photo(cid, fid, caption=caption, parse_mode="Markdown")
            await _pin_message(cid, message.message_id, b)
            return True
        except TelegramError:
            pass
    return False


def cancel(tasks: dict[int, asyncio.Task], cid: int) -> bool:
    t = tasks.pop(cid, None)
    if t and not t.done():
        t.cancel()
        return True
    return False


def cancel_all(cid: int) -> list:
    stopped = []
    if cancel(nc_tasks,          cid): stopped.append("NC loop")
    if cancel(spam_tasks,        cid): stopped.append("Spam loop")
    if cancel(slide_tasks,       cid): stopped.append("TargetSlide loop")
    if cancel(picraid_tasks,     cid): stopped.append("PicRaid loop")
    if cancel(crashnc_tasks,     cid): stopped.append("CrashNC")
    if cancel(crashnc2_tasks,    cid): stopped.append("CrashNC2")
    if cancel(crashnc3_tasks,    cid): stopped.append("CrashNC3")
    if swipe_active.pop(cid, None) is not None: stopped.append("Swipe reply")
    if cancel(ftnc_tasks,        cid): stopped.append("FTNC rename")
    if react_config.pop(cid, None) is not None: stopped.append("Auto-React")
    return stopped


def _make_request() -> HTTPXRequest:
    """HTTPXRequest — optimized for low-latency, high-throughput rename ops."""
    return HTTPXRequest(
        connection_pool_size=256,     # larger pool = less waiting for free connections
        connect_timeout=10.0,         # fail fast on dead connections
        read_timeout=20.0,            # shorter read timeout = less ping bloat
        write_timeout=60.0,
    )


async def load_bots(tokens: list) -> list:
    result = []
    for tok in tokens:
        tok = tok.strip()
        if not tok:
            continue
        try:
            b  = Bot(tok, request=_make_request())
            me = await b.get_me()
            result.append(b)
            log.info("✅ Bot loaded: @%s", me.username)
        except TelegramError as e:
            log.error("❌ Token ...%s failed: %s", tok[-6:], e)
    return result


