async def _rush_bot_rename(bot: Bot, cid: int, name_fn, active: list,
                           stagger: float = 0.0) -> None:
    """Single-bot rename stream — adaptive backoff on flood, max 5s.
    After serving Telegram's mandatory RetryAfter wait, reset delay to BASE
    so we immediately run at full speed again — no extra penalty on top."""
    if stagger:
        await asyncio.sleep(stagger)
    BASE_DELAY   = 0.05            # 50ms base — stable sweet-spot
    MAX_DELAY    = 5.0             # self-imposed cap: max 5s per flood event
    delay        = BASE_DELAY
    clean_streak = 0
    while active[0]:
        try:
            await bot.set_chat_title(cid, name_fn())
            await asyncio.sleep(delay)
            clean_streak += 1
            if clean_streak >= 3 and delay > BASE_DELAY:
                delay        = max(BASE_DELAY, delay * 0.5)
                clean_streak = 0
        except RetryAfter as e:
            wait         = e.retry_after
            clean_streak = 0
            await asyncio.sleep(min(wait, MAX_DELAY))  # serve Telegram wait, cap 5s
            delay = BASE_DELAY                          # reset — fresh 50ms after flood
        except BadRequest:
            await asyncio.sleep(0.5)
        except asyncio.CancelledError:
            break
        except Exception:
            await asyncio.sleep(0.5)


async def _rush_bot_spam(bot: Bot, cid: int, text_fn, active: list,
                         stagger: float = 0.0) -> None:
    """Single-bot spam stream — 0-delay when clean, adaptive backoff on flood.
    On RetryAfter: grow delay (cap 5s). After 5 clean sends: halve back to 0."""
    if stagger:
        await asyncio.sleep(stagger)
    delay        = 0.0
    clean_streak = 0
    while active[0]:
        try:
            await _send_bot_message(bot, cid, text_fn())
            await asyncio.sleep(0)          # yield to event loop, no real wait
            clean_streak += 1
            if clean_streak >= 5 and delay > 0.0:
                delay        = max(0.0, delay * 0.5)
                clean_streak = 0
        except RetryAfter as e:
            wait         = e.retry_after
            delay        = min(delay * 1.5 + wait, 5.0)
            clean_streak = 0
            await asyncio.sleep(wait)
        except asyncio.CancelledError:
            break
        except Exception:
            await asyncio.sleep(0.1)


async def _nc_launcher(cid: int, name_fn) -> None:
    """Launch RENAME_STREAMS independent rename streams per bot — all bots, full speed."""
    active = [True]
    bots_to_use = pool()
    streams = RENAME_STREAMS
    subs = [
        asyncio.create_task(_rush_bot_rename(
            b, cid, name_fn, active,
            stagger=(i * streams + j) * 0.01
        ))
        for i, b in enumerate(bots_to_use)
        for j in range(streams)
    ]
    try:
        await asyncio.gather(*subs)
    except asyncio.CancelledError:
        active[0] = False
        for t in subs:
            t.cancel()
        await asyncio.gather(*subs, return_exceptions=True)
        raise


_LONG_NL: str = "\n" * 15   # 15 blank lines — makes name tall without adding width

def _pad(text: str) -> str:
    """Append newlines so the group name is vertically long (not horizontally wide)."""
    return text + _LONG_NL


