async def cmd_mute(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~mute [time] — reply on a user's message to mute them in this chat."""
    if not update.message or not is_auth(update.effective_user.id): return
    cid = update.effective_chat.id
    duration = None
    mute_args = arg(update).split()
    if mute_args:
        duration = parse_duration(mute_args[0])
        if mute_args[0] and duration is None:
            await update.message.reply_text(
                "⚠️ Time `30s`, `5m`, `2h` ya `1d` format mein do.",
                parse_mode="Markdown",
            )
            return

    if not update.message.reply_to_message or not update.message.reply_to_message.from_user:
        await update.message.reply_text(
            "❌ Pehle target ke kisi *message pe reply* karo, phir `~mute` likho.",
            parse_mode="Markdown",
        )
        return

    rep_user = update.message.reply_to_message.from_user
    uid  = rep_user.id
    name = rep_user.first_name

    if is_auth(uid):
        await update.message.reply_text(
            "⚠️ Owner/sudo ko mute nahi kar sakte.", parse_mode="Markdown"
        )
        return

    restricted = False
    for b in pool():
        try:
            from telegram import ChatPermissions
            await b.restrict_chat_member(
                cid, uid,
                permissions=ChatPermissions(
                    can_send_messages=False,
                    can_send_other_messages=False,
                    can_add_web_page_previews=False,
                ),
            )
            restricted = True
            break
        except Exception:
            continue

    muted_users.setdefault(cid, set()).add(uid)
    if duration:
        mute_expiries.setdefault(cid, {})[uid] = time.time() + duration
    else:
        mute_expiries.setdefault(cid, {}).pop(uid, None)
    save_muted_users(muted_users)
    save_feature_state()

    expiry_txt = f" for `{format_remaining(duration)}`" if duration else " permanently"
    status_txt = "✅ Telegram restrict + mute saved" if restricted else "⚠️ Bot lacks restrict permission — mute saved locally"
    await update.message.reply_text(
        f"🔇 *MUTED!*\n"
        f"👤 User: `{name}` (`{uid}`)\n"
        f"📝 {status_txt}{expiry_txt}",
        parse_mode="Markdown",
    )


async def cmd_unmute(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~unmute — reply on a user's message to remove their mute."""
    if not update.message or not is_auth(update.effective_user.id): return
    cid = update.effective_chat.id

    if not update.message.reply_to_message or not update.message.reply_to_message.from_user:
        await update.message.reply_text(
            "❌ Pehle target ke kisi *message pe reply* karo, phir `~unmute` likho.",
            parse_mode="Markdown",
        )
        return

    rep_user = update.message.reply_to_message.from_user
    uid  = rep_user.id
    name = rep_user.first_name

    was_muted = uid in muted_users.get(cid, set())
    muted_users.setdefault(cid, set()).discard(uid)
    mute_expiries.setdefault(cid, {}).pop(uid, None)
    if not mute_expiries.get(cid):
        mute_expiries.pop(cid, None)
    if not muted_users.get(cid):
        muted_users.pop(cid, None)
    save_muted_users(muted_users)
    save_feature_state()

    unrestricted = False
    for b in pool():
        try:
            from telegram import ChatPermissions
            await b.restrict_chat_member(
                cid, uid,
                permissions=ChatPermissions(
                    can_send_messages=True,
                    can_send_other_messages=True,
                    can_add_web_page_previews=True,
                    can_send_polls=True,
                    can_change_info=False,
                    can_invite_users=True,
                    can_pin_messages=False,
                ),
            )
            unrestricted = True
            break
        except Exception:
            continue

    if not was_muted and not unrestricted:
        await update.message.reply_text(
            f"ℹ️ `{name}` muted nahi tha.", parse_mode="Markdown"
        )
        return

    status_txt = "✅ Telegram restrict hataya + mute removed" if unrestricted else "⚠️ Bot lacks restrict perm — mute record removed"
    await update.message.reply_text(
        f"🔊 *UNMUTED!*\n"
        f"👤 User: `{name}` (`{uid}`)\n"
        f"📝 {status_txt}",
        parse_mode="Markdown",
    )


