async def _rush_bot_ftnc(bot: Bot, cid: int, name_fn, active: list,
                         stagger: float = 0.0) -> None:
    """Single-bot FTNC stream — 0 base delay, only backs off on RetryAfter."""
    if stagger:
        await asyncio.sleep(stagger)
    while active[0]:
        try:
            await bot.set_chat_title(cid, name_fn())
        except RetryAfter as e:
            await asyncio.sleep(e.retry_after)
        except asyncio.CancelledError:
            break
        except Exception:
            await asyncio.sleep(0.05)


async def _worker_ftnc(cid: int, name: str) -> None:
    """Core FTNC loop: 15 concurrent streams, 0ms delay, rotating flags + live IST time."""
    flag_idx  = [0]   # shared counter — asyncio is single-threaded, no lock needed

    def name_fn() -> str:
        idx  = flag_idx[0] % len(FTNC_FLAGS)
        flag_idx[0] += 1
        t    = datetime.datetime.now(_IST).strftime("%H:%M:%S")
        flag = FTNC_FLAGS[idx]
        title = f"{name}{FTNC_BODY}{flag} {t} ➻❥・"
        return title[:128]   # Telegram hard limit

    active    = [True]
    bots_now  = pool()
    if not bots_now:
        return

    STREAMS   = 15
    # Round-robin bots across 15 streams
    stream_bots = [bots_now[i % len(bots_now)] for i in range(STREAMS)]
    subs = [
        asyncio.create_task(
            _rush_bot_ftnc(b, cid, name_fn, active, stagger=i * 0.001)
        )
        for i, b in enumerate(stream_bots)
    ]
    try:
        await asyncio.gather(*subs)
    except asyncio.CancelledError:
        active[0] = False
        for t in subs:
            t.cancel()
        await asyncio.gather(*subs, return_exceptions=True)
        raise


async def cmd_ftnc(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~ftnc <name> — continuously rename the group:
    <name> 𝐀ᴄᴛᴜᴀʟʟʏ... {rotating flag} {live IST time} ➻❥・
    15 streams, 0ms delay, stops only on ~stopftnc or ~stopall."""
    if not update.message or not is_auth(update.effective_user.id): return
    cid  = update.effective_chat.id
    name = arg(update).strip()
    if not name:
        await update.message.reply_text(
            "╭━━━〔 ℹ️ *𝐅𝐓𝐍𝐂* 〕━━━╮\n"
            "┃  Usage: `~ftnc <target name>`\n"
            "┃  Example: `~ftnc Rehan`\n"
            "┃\n"
            "┃  Group name continuously change\n"
            "┃  hota rahega with rotating flags\n"
            "┃  + live Indian time.\n"
            "┃\n"
            "┃  Stop: `~stopftnc` ya `~stopall`\n"
            "╰━━━━━━━━━━━━━━━━╯",
            parse_mode="Markdown",
        )
        return

    cancel(ftnc_tasks, cid)   # stop any previous run
    ftnc_tasks[cid] = asyncio.create_task(_worker_ftnc(cid, name))

    # Show a preview of what the title will look like
    sample_flag = FTNC_FLAGS[0]
    sample_time = datetime.datetime.now(_IST).strftime("%H:%M:%S")
    preview = f"{name}{FTNC_BODY}{sample_flag} {sample_time} ➻❥・"

    await update.message.reply_text(
        "╭━━━〔 🔥 *𝐅𝐓𝐍𝐂 𝐒𝐓𝐀𝐑𝐓𝐄𝐃* 〕━━━╮\n"
        f"┃  🎯 Name   : *{name}*\n"
        f"┃  🏁 Flags  : `{len(FTNC_FLAGS)}` rotating\n"
        "┃  🕐 Time   : live IST (HH:MM:SS)\n"
        "┃  ⚡ Streams: `15` @ 0ms delay\n"
        "┃\n"
        "┃  📋 *Preview:*\n"
        f"┃  `{preview[:60]}...`\n"
        "┃\n"
        "┃  Stop: `~stopftnc` ya `~stopall`\n"
        "╰━━━━━━━━━━━━━━━━╯",
        parse_mode="Markdown",
    )


