async def cmd_setmenu(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """~setmenu — reply to any photo or video to set it as the menu media."""
    global menu_pic, menu_pic_type

    if not update.message or not is_auth(update.effective_user.id):
        return

    rep = update.message.reply_to_message
    if not rep:
        await update.message.reply_text(
            "❌ Kisi *photo ya video* pe reply karo `~setmenu` ke saath.",
            parse_mode="Markdown",
        )
        return

    try:
        if rep.photo:
            fid           = rep.photo[-1].file_id
            menu_pic_type = "photo"
        elif rep.video:
            fid           = rep.video.file_id
            menu_pic_type = "video"
        elif rep.animation:
            fid           = rep.animation.file_id
            menu_pic_type = "video"
        else:
            await update.message.reply_text("❌ Sirf photo ya video support hoti hai.")
            return

        menu_pic = fid
        save_runtime_config(LOOP_DELAY, GAMEOVER_IMG, menu_pic, menu_pic_type, gameover_pic, gameover_pic_type)
        await update.message.reply_text(
            f"✅ Menu *{menu_pic_type}* set ho gayi!\nAb `~help` pe yahi media aayegi.",
            parse_mode="Markdown",
        )

    except Exception as e:
        await update.message.reply_text(f"❌ Error: {e}")


async def cmd_setmenuvid(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~setmenuvid — reply to a video and save it as the help-menu video."""
    if not update.message or not is_auth(update.effective_user.id):
        return
    reply = update.message.reply_to_message
    if not reply or not (reply.video or reply.animation):
        await update.message.reply_text(
            "❌ Kisi video/GIF par reply karke `~setmenuvid` bhejo.",
            parse_mode="Markdown",
        )
        return
    global menu_pic, menu_pic_type
    menu_pic = reply.video.file_id if reply.video else reply.animation.file_id
    menu_pic_type = "video"
    save_runtime_config(
        LOOP_DELAY, GAMEOVER_IMG, menu_pic, menu_pic_type, gameover_pic, gameover_pic_type
    )
    await update.message.reply_text(
        "✅ Menu video set ho gayi. Ab `~help` par yahi video aayegi.",
        parse_mode="Markdown",
    )


async def cmd_removemenupic(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id): return
    global menu_pic, menu_pic_type
