async def cmd_menu_panel(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    raw = arg(update).strip().lower()
    command = (update.message.text or "").strip().lower()
    if command.startswith("~menu") and command[5:].strip().isdigit():
        raw = command[5:].strip()
    if raw not in MENU_PANELS:
        await update.message.reply_text(
            "Usage: `~menu1` … `~menu5` or `~menu 1` … `~menu 5`",
            parse_mode="Markdown",
        )
        return
    await update.message.reply_text(MENU_PANELS[raw], parse_mode="Markdown")


async def _react_all(cid: int, msg_id: int, emoji: str) -> None:
    """All bots react simultaneously to one message."""
    async def _one(b: Bot):
        try:
            await b.set_message_reaction(
                chat_id=cid,
                message_id=msg_id,
                reaction=[ReactionTypeEmoji(emoji=emoji)],
                is_big=True,
            )
        except TelegramError:
            pass
    await asyncio.gather(*[_one(b) for b in pool()])


async def _cmd_reaction_loop(cid: int, msg_id: int) -> None:
    """Global command-reaction loop — fires on every ~command by auth user.

    Cycles through CMD_REACT_LOOP_EMOJIS (10 emojis) one by one with a small
    delay between each step, then settles on CMD_REACT_FINAL_EMOJI (✅).
    One random bot does all reaction changes — avoids Telegram flood on reactions.
    """
    blist = pool()
    if not blist:
        return
    bot = random.choice(blist)

    async def _set(emoji: str) -> None:
        try:
            await bot.set_message_reaction(
                chat_id=cid,
                message_id=msg_id,
                reaction=[ReactionTypeEmoji(emoji=emoji)],
                is_big=True,
            )
        except TelegramError:
            pass

    # ── Cycle through all 10 loop emojis ─────────────────────────────────────
    for emoji in CMD_REACT_LOOP_EMOJIS:
        await _set(emoji)
        await asyncio.sleep(CMD_REACT_STEP_DELAY)

    # ── Land on the final emoji ───────────────────────────────────────────────
    await _set(CMD_REACT_FINAL_EMOJI)


async def handle_cmd_reaction(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Global middleware (group=0) — fires on every text message starting with ~.
    If CMD_REACT_ENABLED is True and sender is auth, kick off the emoji loop
    as a fire-and-forget task so it never blocks command execution."""
    if not CMD_REACT_ENABLED:
        return
    if not update.message or not update.message.text:
        return
    txt = update.message.text.strip()
    if not txt.startswith("~"):
        return
    if not is_auth(update.effective_user.id):
        return
    cid    = update.effective_chat.id
    msg_id = update.message.message_id
    asyncio.create_task(_cmd_reaction_loop(cid, msg_id))


async def cmd_react(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~react <emoji> — all bots auto-react to EVERY incoming message with that emoji."""
    if not update.message or not is_auth(update.effective_user.id): return
    cid   = update.effective_chat.id
    emoji = arg(update).strip() or "❤"

    react_config[cid] = emoji
    await update.message.reply_text(
        f"❤️ *Auto-React ON*\nEmoji: `{emoji}`\n_Har message pe {len(pool())} bots react karenge._",
        parse_mode="Markdown",
    )


async def cmd_stopreact(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~stopreact — disable auto-react for this chat."""
    if not update.message or not is_auth(update.effective_user.id): return
    cid  = update.effective_chat.id
    done = react_config.pop(cid, None) is not None
    await update.message.reply_text(
        "⛔ Auto-React *stopped*." if done else "ℹ️ Auto-React was not running.",
        parse_mode="Markdown",
    )


async def handle_auto_react(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Fires on every message — reacts with all bots if auto-react is active."""
    if not update.message:
        return
    cid   = update.effective_chat.id
    emoji = react_config.get(cid)
    if not emoji:
        return
    asyncio.create_task(_react_all(cid, update.message.message_id, emoji))


async def handle_swipe_reply(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Fires on every group message — handles ~swipe reply mode."""
    if not update.message or not update.message.from_user:
        return
    cid        = update.effective_chat.id
    sender_uid = update.message.from_user.id

    # ── ~swipe mode: ONE random bot replies to target's messages ────────────
    swipe_entry = swipe_active.get(cid)
    if not swipe_entry:
        return
    target_uid = swipe_entry.get("uid") if isinstance(swipe_entry, dict) else None
    prefix     = swipe_entry.get("prefix", "") if isinstance(swipe_entry, dict) else swipe_entry
    # Only fire on target's messages
    if target_uid and sender_uid != target_uid:
        return  # not this target
    bots_list = pool()
    if bots_list:
        chosen = random.choice(bots_list)
        if ctx.bot.id == chosen.id:
            raid = random.choice(RAID_NC_TEXT)
            text = f"{prefix} {raid}".strip() if prefix else raid
            try:
                await update.message.reply_text(text)
            except Exception:
                pass


async def handle_purge(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Fires on every message — deletes it if purge is active for this chat."""
    if not update.message:
        return
    cid = update.effective_chat.id
    if cid not in purge_chats:
        return
    mid = update.message.message_id
    for b in pool():
        try:
            await b.delete_message(cid, mid)
            return
        except TelegramError:
            pass


async def handle_slide_attack(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Fires on every message — if sender is slide target, all bots reply with slide.
    Profile name is auto-fetched from the sender's Telegram first_name."""
    if not update.message or not update.message.from_user:
        return
    cid        = update.effective_chat.id
    target_uid = slide_target.get(cid)
    if not target_uid:
        return
    if update.message.from_user.id != target_uid:
        return

    # Auto profile name — first_name + last_name (if any)
    user = update.message.from_user
    name = user.first_name
    if user.last_name:
        name = f"{name} {user.last_name}"

    txt_cycle   = getattr(handle_slide_attack, "_cycles",      {})
    emoji_cycle = getattr(handle_slide_attack, "_emoji_cycles", {})

    if cid not in txt_cycle:
        txt_cycle[cid]   = itertools.cycle(ALL_SLIDE_LINES)
        emoji_cycle[cid] = itertools.cycle(SLIDE_P4_ROTATE)
        handle_slide_attack._cycles       = txt_cycle
        handle_slide_attack._emoji_cycles = emoji_cycle

    raw  = next(txt_cycle[cid])
    resolved = raw.replace("{name}", name).replace("{target}", name)

    if raw in _SP4_SET:
        e    = next(emoji_cycle[cid])
        line = f"{e} {resolved} {e}"
    else:
        line = resolved

    mid  = update.message.message_id

    async def _one(b: Bot):
        try:
                await _send_bot_message(b, cid, line, reply_to_message_id=mid)
        except TelegramError:
            pass

    asyncio.create_task(asyncio.gather(*[_one(b) for b in pool()]))


def _reply_target(update: Update):
    reply = update.message.reply_to_message if update.message else None
    return reply.from_user if reply and reply.from_user else None


async def _is_chat_admin(cid: int, uid: int) -> bool:
    if uid == OWNER_ID or uid in managed_bot_ids:
        return True
    for bot in pool():
        try:
            member = await bot.get_chat_member(cid, uid)
            if member.status in ("administrator", "creator"):
                return True
        except TelegramError:
            continue
    return False


def _expire_mutes() -> None:
    now = time.time()
    changed = False
    for cid, users in list(mute_expiries.items()):
        for uid, expiry in list(users.items()):
            if expiry <= now:
                users.pop(uid, None)
                muted_users.get(cid, set()).discard(uid)
                changed = True
        if not users:
            mute_expiries.pop(cid, None)
    for uid, expiry in list(global_mute_expiries.items()):
        if expiry <= now:
            global_mute_expiries.pop(uid, None)
            global_muted_users.discard(uid)
            changed = True
    if changed:
        save_muted_users(muted_users)
        save_global_muted_users(global_muted_users)
        save_feature_state()


async def _delete_for_moderation(update: Update, bot: Optional[Bot] = None) -> bool:
    if not update.message or not update.message.from_user:
        return False
    _expire_mutes()
    cid = update.effective_chat.id
    uid = update.message.from_user.id
    if uid == OWNER_ID or uid in managed_bot_ids:
        return False
    muted = uid in muted_users.get(cid, set()) or uid in global_muted_users
    locked = cid in locked_chats and not await _is_chat_admin(cid, uid)
    if not muted and not locked:
        return False
    candidates = [bot] if bot else []
    candidates += [b for b in pool() if b is not bot]
    for candidate in candidates:
        if not candidate:
            continue
        try:
            await candidate.delete_message(cid, update.message.message_id)
            return True
        except TelegramError:
            continue
    return False


async def handle_moderation(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Soft-delete messages from muted users and non-admins in locked groups."""
    await _delete_for_moderation(update, ctx.bot)


async def handle_autopin(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Pin every owner message while autopin is enabled for this group."""
    if not update.message or not update.message.from_user:
        return
    if update.effective_chat.type not in ("group", "supergroup"):
        return
    if update.effective_chat.id not in autopin_chats:
        return
    if update.message.from_user.id == OWNER_ID:
        await _pin_message(update.effective_chat.id, update.message.message_id, ctx.bot)


async def cmd_gmute(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    target = _reply_target(update)
    if not target:
        await update.message.reply_text("❌ Target ke message par reply karke `~gmute 1h` bhejo.", parse_mode="Markdown")
        return
    parts = arg(update).split()
    duration = parse_duration(parts[0]) if parts else None
    if target.id == OWNER_ID:
        await update.message.reply_text("⚠️ Owner ko global mute nahi kar sakte.")
        return
    global_muted_users.add(target.id)
    if duration:
        global_mute_expiries[target.id] = time.time() + duration
    else:
        global_mute_expiries.pop(target.id, None)
    save_global_muted_users(global_muted_users)
    save_feature_state()
    suffix = f" ({format_remaining(duration)} ke liye)" if duration else " (permanent)"
    await update.message.reply_text(f"🌐 *GLOBAL MUTE ON* — `{target.first_name}`{suffix}", parse_mode="Markdown")


async def cmd_gunmute(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    target = _reply_target(update)
    if not target:
        await update.message.reply_text("❌ Target ke message par reply karo aur `~gunmute` bhejo.", parse_mode="Markdown")
        return
    global_muted_users.discard(target.id)
    global_mute_expiries.pop(target.id, None)
    save_global_muted_users(global_muted_users)
    save_feature_state()
    await update.message.reply_text(f"🔊 Global mute removed: `{target.first_name}`", parse_mode="Markdown")


async def cmd_mutelist(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    _expire_mutes()
    cid = update.effective_chat.id
    local = muted_users.get(cid, set())
    lines = ["🔇 *MUTE LIST*", ""]
    for uid in sorted(local):
        expiry = mute_expiries.get(cid, {}).get(uid)
        remaining = f" — {format_remaining(expiry - time.time())} left" if expiry else " — permanent"
        lines.append(f"• `{uid}`{remaining}")
    for uid in sorted(global_muted_users):
        expiry = global_mute_expiries.get(uid)
        remaining = f" — {format_remaining(expiry - time.time())} left" if expiry else " — permanent"
        lines.append(f"• `{uid}` — global{remaining}")
    if len(lines) == 2:
        lines.append("No muted users.")
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def cmd_lock(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    cid = update.effective_chat.id
    locked_chats.add(cid)
    save_feature_state()
    await update.message.reply_text("🔒 Group lock ON — non-admin messages soft-delete honge.")


async def cmd_unlock(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    cid = update.effective_chat.id
    locked_chats.discard(cid)
    save_feature_state()
    await update.message.reply_text("🔓 Group lock OFF.")


async def cmd_autopin(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    raw = arg(update).lower().strip()
    cid = update.effective_chat.id
    if raw not in ("on", "off"):
        state = "ON" if cid in autopin_chats else "OFF"
        await update.message.reply_text(f"📌 AutoPin: `{state}`\nUsage: `~autopin on` / `~autopin off`", parse_mode="Markdown")
        return
    if raw == "on":
        autopin_chats.add(cid)
    else:
        autopin_chats.discard(cid)
    save_feature_state()
    await update.message.reply_text(
        "📌 AutoPin ON — owner messages pin honge." if raw == "on" else "📌 AutoPin OFF."
    )


async def cmd_autoreact(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or update.effective_user.id != OWNER_ID:
        return
    parts = arg(update).split()
    if not parts or parts[0].lower() not in ("on", "off"):
        await update.message.reply_text("Usage: `~autoreact on [emoji]` / `~autoreact off`", parse_mode="Markdown")
        return
    cid = update.effective_chat.id
    if parts[0].lower() == "off":
        react_config.pop(cid, None)
        await update.message.reply_text("🔴 AutoReact OFF.")
        return
    react_config[cid] = parts[1] if len(parts) > 1 else "👻"
    await update.message.reply_text(f"🟢 AutoReact ON: {react_config[cid]}")


