    success, failed, error = await _set_all_bot_profile("set_my_name", name=name[:64])
    await update.message.reply_text(f"🤖 Name updated: `{success}` bots, failed: `{failed}`{f'\\n`{error[:300]}`' if error else ''}", parse_mode="Markdown")


