async def cmd_translate(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id):
        return
    parts = arg(update).split(None, 1)
    if len(parts) < 2:
        await update.message.reply_text("Usage: `~translate [lang] [text]`", parse_mode="Markdown")
        return
    lang, text = parts
    try:
        url = (
            "https://api.mymemory.translated.net/get?q="
            + urllib.parse.quote(text, safe="")
            + "&langpair=auto|"
            + urllib.parse.quote(lang, safe="")
        )
        data = await _http_get_json(url)
        translated = data.get("responseData", {}).get("translatedText")
        if not translated:
            raise ValueError("translation unavailable")
        await update.message.reply_text(f"🌐 `{lang}`: {translated}", parse_mode="Markdown")
    except Exception as exc:
        await update.message.reply_text(f"❌ Translation failed: `{str(exc)[:500]}`", parse_mode="Markdown")


