_CHAT_SAVE_COUNTER = [0]

async def handle_track_chat(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Fires on every message (group=10) — ONLY tracks known GCs.
    Multimode + DM routing is handled inside warfare_wrap on each command handler."""
    global _known_chats_dirty
    if not update.message:
        return
    chat = update.effective_chat
    if chat and chat.type in ("group", "supergroup"):
        cid = chat.id
        if cid not in known_chats:
            known_chats.add(cid)
            _known_chats_dirty = True
        _CHAT_SAVE_COUNTER[0] += 1
        if _known_chats_dirty and _CHAT_SAVE_COUNTER[0] % 20 == 0:
            save_known_chats(known_chats)
            _known_chats_dirty = False


async def _exec_in_chat(cmd: str, raw_arg: str, cid: int) -> bool:
    """Directly execute a warfare command's worker in the given cid.
    Returns True if the command was recognised and dispatched."""
    name = raw_arg.strip() or "GROUP"
    cmd  = cmd.lower()

    # ── NC family ────────────────────────────────────────────────────────────
    if cmd == "nc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_nc(cid, name, NC_EMOJIS))
    elif cmd == "fucknc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_nc(cid, name, FUCK_NC_TEXT))
    elif cmd == "ncloop":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_nc(cid, name, NC_LOOP_TEXT, god=True))
    elif cmd == "raidnc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_raidnc(cid, name))
    elif cmd == "timenc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_timenc(cid, name))
    elif cmd == "longnc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_longnc(cid, name))
    elif cmd == "nc2":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_nc2(cid, name))
    elif cmd == "aninc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_aninc(cid, name))
    elif cmd == "glitchnc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_glitchnc(cid, name))
    elif cmd == "crashnc":
        cancel(crashnc_tasks, cid)
        crashnc_tasks[cid] = asyncio.create_task(_worker_crashnc(cid, name))
    elif cmd == "glitchnc2":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_glitchnc2(cid, name))
    elif cmd == "crashnc2":
        cancel(crashnc2_tasks, cid)
        crashnc2_tasks[cid] = asyncio.create_task(_worker_crashnc2(cid, name))
    elif cmd == "crashnc3":
        cancel(crashnc3_tasks, cid)
        crashnc3_tasks[cid] = asyncio.create_task(_worker_crashnc3(cid, name))
    elif cmd == "stopcrashnc2":
        cancel(crashnc2_tasks, cid)
    elif cmd == "stopcrashnc3":
        cancel(crashnc3_tasks, cid)
    elif cmd == "glitchnc3":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_glitchnc3(cid, name))
    elif cmd == "hnc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_hnc(cid, name))
    elif cmd == "inc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_inc(cid, name))
    elif cmd == "jnc":
        cancel(nc_tasks, cid)
        nc_tasks[cid] = asyncio.create_task(_worker_jnc(cid, name))
    # ── Spam family ──────────────────────────────────────────────────────────
    elif cmd == "spam":
        cancel(spam_tasks, cid)
        spam_tasks[cid] = asyncio.create_task(_worker_spam(cid, name))
    elif cmd == "crashtextraid":
        cancel(spam_tasks, cid)
        spam_tasks[cid] = asyncio.create_task(_worker_crashtext(cid))
    elif cmd == "picraid":
        if cid in raid_pic:
            cancel(picraid_tasks, cid)
            picraid_tasks[cid] = asyncio.create_task(_worker_picraid(cid, raid_pic[cid]))
    # ── Stop family ──────────────────────────────────────────────────────────
    elif cmd == "stopnc":
        cancel(nc_tasks, cid)
    elif cmd == "stopspam":
        cancel(spam_tasks, cid)
    elif cmd == "stoppicraid":
        cancel(picraid_tasks, cid)
    elif cmd == "stopcrashnc":
        cancel(crashnc_tasks, cid)
    elif cmd in ("stopall", "stopswipe"):
        cancel_all(cid)
    else:
        return False
    return True


async def _broadcast_to_all_except(cmd: str, raw_arg: str, source_cid) -> None:
    """Concurrent broadcast to all known GCs — supports 100+ GCs without blocking.
    Uses Semaphore(20) so max 20 GCs are dispatched simultaneously.
    50ms stagger every 10 tasks to avoid burst spikes."""
    targets = [c for c in known_chats if c != source_cid]
    if not targets:
        return

    sem = asyncio.Semaphore(20)

    async def _one(cid: int, idx: int):
        async with sem:
            try:
                await _exec_in_chat(cmd, raw_arg, cid)
            except Exception:
                pass

    tasks = []
    for idx, cid in enumerate(targets):
        tasks.append(asyncio.create_task(_one(cid, idx)))
        if idx > 0 and idx % 10 == 0:
            await asyncio.sleep(0.05)   # small stagger every 10 tasks

    if tasks:
        await asyncio.gather(*tasks, return_exceptions=True)



