_REGULAR_GROUP_ERR = (
    "method is available for supergroup",
    "can't promote non-admin",
    "can't demote chat creator",
    "not enough rights",
    "method is available only for supergroup",
)

async def _promote_bot_in_chat(b: Bot, cid: int) -> tuple[str, bool, bool]:
    """Try to promote a bot in a chat.

    Returns: (display_name, success, is_regular_group)
    is_regular_group = True when the failure is because the chat is a plain group
    (not a supergroup), which is a Telegram API limitation — cannot be fixed.
    """
    try:
        me = await b.get_me()
        await b.promote_chat_member(
            cid, me.id,
            can_change_info=True,
            can_delete_messages=True,
            can_invite_users=True,
            can_restrict_members=True,
            can_pin_messages=True,
            can_manage_chat=True,
            can_post_messages=True,
        )
        return f"@{me.username}", True, False
    except BadRequest as e:
        err_lower = str(e).lower()
        is_reg = any(k in err_lower for k in _REGULAR_GROUP_ERR)
        log.warning("[promote] cid=%s err=%s", cid, e)
        return str(e)[:50], False, is_reg
    except Forbidden as e:
        log.warning("[promote] cid=%s Forbidden: %s", cid, e)
        return "Forbidden (bot not member/kicked)", False, False
    except TelegramError as e:
        log.warning("[promote] cid=%s err=%s", cid, e)
        return str(e)[:50], False, False


async def cmd_upall(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~upall — promote all hosted bots as admins in the CURRENT group."""
    if not update.message or not is_auth(update.effective_user.id): return
    cid   = update.effective_chat.id
    blist = pool()
    if not blist:
        await update.message.reply_text("⚠️ <b>Koi bot loaded nahi hai.</b>", parse_mode="HTML")
        return

    raw     = await asyncio.gather(*[_promote_bot_in_chat(b, cid) for b in blist], return_exceptions=True)
    # Normalise to 3-tuple — handle unexpected exceptions from gather
    results = []
    for r in raw:
        if isinstance(r, Exception):
            results.append((str(r)[:50], False, False))
        else:
            results.append(r)   # already (name, ok, is_reg_group)

    done     = sum(1 for _, ok, _ in results if ok)
    fail     = len(results) - done
    reg_fail = sum(1 for _, ok, reg in results if not ok and reg)

    lines = ["🔓 <b>UPALL — Current GC</b>", ""]
    for name, ok, is_reg in results:
        icon = "✅" if ok else ("⚠️" if is_reg else "❌")
        lines.append(f"{icon} {name}")

    lines += ["", f"✅ Promoted : <code>{done}</code>  ❌ Failed: <code>{fail}</code>"]
    if reg_fail:
        lines.append(
            f"\n⚠️ <b>{reg_fail} regular group(s)</b> — Telegram API se admin banana"
            f" impossible hai.\nIn groups mein manually bot ko admin banao."
        )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")


async def _autoadmin_worker(targets: list[int], progress_msg) -> None:
    """Background task: promote all bots as admins in every target GC.

    Regular groups (non-supergroup) are counted separately because
    Telegram Bot API cannot promote members in regular groups — Telegram limitation.
    """
    blist    = pool()
    total    = len(targets)
    gc_ok    = 0
    gc_fail  = 0
    gc_reg   = 0   # regular group failures (API limitation, not our bug)
    lock     = asyncio.Lock()
    sem      = asyncio.Semaphore(10)

    async def _one_gc(cid: int) -> None:
        nonlocal gc_ok, gc_fail, gc_reg
        async with sem:
            raw = await asyncio.gather(
                *[_promote_bot_in_chat(b, cid) for b in blist],
                return_exceptions=True,
            )
            results = [
                (r if not isinstance(r, Exception) else (str(r)[:50], False, False))
                for r in raw
            ]
            any_ok  = any(ok  for _, ok,  _   in results)
            any_reg = any(reg for _, _,   reg in results if not _)
            async with lock:
                if any_ok:
                    gc_ok += 1
                elif any_reg:
                    gc_reg += 1   # all bots say "supergroup only"
                else:
                    gc_fail += 1
            done = gc_ok + gc_fail + gc_reg
            if done % 5 == 0 or done == total:
                try:
                    await progress_msg.edit_text(
                        f"⚙️ <b>AUTOADMIN IN PROGRESS</b>\n"
                        f"✅ Supergroups done   : <code>{gc_ok}</code>\n"
                        f"⚠️ Regular groups     : <code>{gc_reg}</code> (manual needed)\n"
                        f"❌ Failed (other)     : <code>{gc_fail}</code>\n"
                        f"⏳ Total : <code>{done}</code> / <code>{total}</code>",
                        parse_mode="HTML",
                    )
                except TelegramError:
                    pass
            await asyncio.sleep(0.08)

    await asyncio.gather(*[_one_gc(cid) for cid in targets], return_exceptions=True)

    reg_note = (
        f"\n\n⚠️ <b>{gc_reg} regular group(s)</b> — Telegram API regular groups mein"
        f" bots ko admin nahi bana sakta.\n"
        f"<i>In groups mein manually bot ko admin banao ya group ko supergroup mein convert karo.</i>"
    ) if gc_reg else ""

    try:
        await progress_msg.edit_text(
            f"✅ <b>AUTOADMIN COMPLETE!</b>\n\n"
            f"🤖 Bots        : <code>{len(blist)}</code>\n"
            f"✅ Supergroups : <code>{gc_ok}</code> done\n"
            f"⚠️ Regular GCs : <code>{gc_reg}</code> (API limit)\n"
            f"❌ Failed      : <code>{gc_fail}</code>\n"
            f"📊 Total GCs   : <code>{total}</code>"
            f"{reg_note}",
            parse_mode="HTML",
        )
    except TelegramError:
        pass


async def cmd_autoadmin(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~autoadmin — promote all hosted bots as admins in ALL known GCs (DM or GC)."""
    if not update.message or not is_auth(update.effective_user.id): return

    blist = pool()
    if not blist:
        await update.message.reply_text(
            "⚠️ <b>Koi bot loaded nahi hai.</b>\n<i>Pehle tokens add karo.</i>",
            parse_mode="HTML",
        )
        return

    targets = list(known_chats)
    # If called from a GC, include current chat too
    src_cid = update.effective_chat.id
    if update.effective_chat.type != "private" and src_cid not in targets:
        targets.append(src_cid)

    if not targets:
        await update.message.reply_text(
            "⚠️ <b>Koi known GC nahi hai!</b>\n"
            "<i>Pehle bot ko kisi group mein join kara.</i>",
            parse_mode="HTML",
        )
        return

    progress_msg = await update.message.reply_text(
        f"⚙️ <b>AUTOADMIN STARTING...</b>\n"
        f"🤖 Bots    : <code>{len(blist)}</code>\n"
        f"🌐 GCs     : <code>{len(targets)}</code>\n"
        f"<i>Sabhi groups mein promote kar raha hoon...</i>",
        parse_mode="HTML",
    )

    asyncio.create_task(_autoadmin_worker(targets, progress_msg))


