def _gameover_caption() -> str:
    """Build the gameover caption with current IST time."""
    from datetime import datetime, timezone, timedelta
    IST      = timezone(timedelta(hours=5, minutes=30))
    now      = datetime.now(IST)
    date_str = now.strftime("%d %B %Y")
    time_str = now.strftime("%I:%M:%S %p") + " IST"
    return (
        f"📅  Dᴀᴛᴇ  :  {date_str}\n"
        f"⏰  Tɪᴍᴇ  :  {time_str}\n\n"
        f"╭──────────────────╮\n"
        f"     🎮 ɢᴀᴍᴇ ᴏᴠᴇʀ ʙʏ\n\n"
            f"   ✦~ ꜱᴏᴛꜰʏ ʙʜᴀɢᴡᴀɴ🚩 ✦\n"
        f"╰──────────────────╯"
    )


async def _send_gameover_to(cid: int, caption: str, bot_idx: int) -> bool:
    """Send the gameover pic (or text fallback) to a single cid.

    bot_idx = which bot to start with (index into pool()).
    Uses index-based assignment — NO shared iterator, so no race condition
    when called from multiple concurrent tasks.

    Auto-removes stale GCs (bot kicked / chat deleted) from known_chats.
    Returns True on success.
    """
    blist = pool()
    if not blist:
        return False

    n = len(blist)
    i = 0  # how many bots we've tried
    while i < n:
        b = blist[(bot_idx + i) % n]
        try:
            if gameover_pic:
                if gameover_pic_type == "video":
                    await b.send_video(cid, gameover_pic, caption=caption, parse_mode="HTML")
                else:
                    await b.send_photo(cid, gameover_pic, caption=caption, parse_mode="HTML")
            elif os.path.isfile(GAMEOVER_IMG):
                with open(GAMEOVER_IMG, "rb") as fh:
                    await b.send_photo(cid, fh, caption=caption, parse_mode="HTML")
            else:
                await b.send_message(cid, caption, parse_mode="HTML")
            return True

        except RetryAfter as e:
            # Telegram says "wait N seconds" — respect it, retry SAME bot
            await asyncio.sleep(e.retry_after + 0.5)
            # Don't increment i — retry same bot after sleeping

        except Forbidden:
            # Bot was kicked / blocked / chat deleted — clean stale entry
            known_chats.discard(cid)
            return False

        except BadRequest as e:
            err = str(e).lower()
            if "chat not found" in err or "deactivated" in err or "migrated" in err:
                known_chats.discard(cid)
                return False
            i += 1  # some other bad request — try next bot

        except TelegramError:
            i += 1  # this bot can't reach cid — try next bot

    return False


async def _gameover_flood_broadcast(
    targets: list[int],
    caption: str,
    progress_cid: int | None,
    progress_msg=None,
) -> tuple[int, int]:
    """Send gameover pic to all targets with flood-safe concurrency for 100+ GCs.

    Strategy:
    - Semaphore(15): max 15 concurrent sends (safe for 100+ GCs)
    - Index-based bot assignment: each GC gets a dedicated starting-bot,
      so concurrent tasks don't share a mutable iterator (no race condition)
    - RetryAfter fully respected inside _send_gameover_to (retries same bot)
    - 50ms stagger between every 10 task launches to avoid burst
    Returns (ok_count, fail_count).
    """
    if not targets:
        return 0, 0

    sem        = asyncio.Semaphore(15)
    ok_count   = 0
    fail_count = 0
    total      = len(targets)
    lock       = asyncio.Lock()
    n_bots     = max(1, len(pool()))

    async def _one(cid: int, idx: int):
        nonlocal ok_count, fail_count
        async with sem:
            # Each GC starts with a different bot — distributes load evenly
            success = await _send_gameover_to(cid, caption, idx % n_bots)
            async with lock:
                if success:
                    ok_count += 1
                else:
                    fail_count += 1
            # Live progress every 10 GCs
            done = ok_count + fail_count
            if progress_msg and done % 10 == 0:
                try:
                    await progress_msg.edit_text(
                        f"📡 <b>GAMEOVER BROADCAST</b>\n"
                        f"✅ Sent   : <code>{ok_count}</code>\n"
                        f"❌ Failed : <code>{fail_count}</code>\n"
                        f"⏳ Total  : <code>{done}</code> / <code>{total}</code>",
                        parse_mode="HTML",
                    )
                except TelegramError:
                    pass

    tasks = []
    for idx, cid in enumerate(targets):
        tasks.append(asyncio.create_task(_one(cid, idx)))
        # Stagger every 10 launches — softens the initial burst for 100+ GCs
        if idx % 10 == 9:
            await asyncio.sleep(0.05)

    await asyncio.gather(*tasks, return_exceptions=True)
    return ok_count, fail_count


async def cmd_gameover(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id): return

    caption   = _gameover_caption()
    chat_type = update.effective_chat.type
    src_cid   = update.effective_chat.id

    # ── Determine target GCs ─────────────────────────────────────────────────
    if chat_type == "private":
        # DM → broadcast to ALL known GCs
        targets = list(known_chats)
        if not targets:
            await update.message.reply_text(
                "⚠️ <b>Koi known GC nahi!</b>\n"
                "<i>Pehle kisi group mein ja — bot woh GC yaad rakhega.</i>",
                parse_mode="HTML",
            )
            return
    else:
        # Called from a GC → broadcast to ALL known GCs (including this one)
        targets = list(known_chats | {src_cid})

    # Stop all running tasks in every target GC first
    for cid in targets:
        cancel_all(cid)

    total = len(targets)

    # Send progress message to caller
    progress_msg = await update.message.reply_text(
        f"🎮 <b>GAMEOVER BROADCAST STARTED!</b>\n"
        f"📡 Sending to <code>{total}</code> group(s)...\n"
        f"<i>Pic ke saath — flood-safe mode (100+ GC support).</i>",
        parse_mode="HTML",
    )

    ok, fail = await _gameover_flood_broadcast(targets, caption, src_cid, progress_msg)

    # Final summary
    try:
        await progress_msg.edit_text(
            f"🎮 <b>GAMEOVER COMPLETE!</b>\n\n"
            f"✅ Sent successfully : <code>{ok}</code> GC(s)\n"
            f"❌ Failed            : <code>{fail}</code> GC(s)\n"
            f"📊 Total targets     : <code>{total}</code>\n"
            f"🤖 Bots used         : <code>{len(pool())}</code>\n\n"
            f"<i>Sab GCs mein tasks bhi band kar diye.</i>\n"
            f"<i>Stale GCs (bot kicked/deleted) auto-removed from tracking.</i>",
            parse_mode="HTML",
        )
    except TelegramError:
        pass


async def cmd_setdelay(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or update.effective_user.id != OWNER_ID: return

    global LOOP_DELAY

    raw = arg(update)
    if not raw:
        await update.message.reply_text(
            f"⏱️ Current delay: `{LOOP_DELAY}s`\nUsage: `~setdelay <seconds>`",
            parse_mode="Markdown",
        )
        return

    try:
        new_delay = float(raw)
    except ValueError:
        await update.message.reply_text("❌ Invalid number. Example: `~setdelay 2.5`", parse_mode="Markdown")
        return

    if new_delay < 0.5:
        await update.message.reply_text("⚠️ Minimum is `0.5s`.", parse_mode="Markdown")
        return
    if new_delay > 300:
        await update.message.reply_text("⚠️ Maximum is `300s`.", parse_mode="Markdown")
        return

    old        = LOOP_DELAY
    LOOP_DELAY = new_delay

    try:
        save_runtime_config(LOOP_DELAY, GAMEOVER_IMG, menu_pic, menu_pic_type, gameover_pic, gameover_pic_type)
    except Exception:
        pass

    await update.message.reply_text(
        f"⏱️ *Delay updated!*\n`{old}s` → `{LOOP_DELAY}s`\n\n"
        "_Running loops pick up the new delay on the next tick._",
        parse_mode="Markdown",
    )




async def cmd_addtoken(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~addtoken <token1> <token2> ... — Owner ek ya multiple tokens ek saath add kar sakta hai.
    Tokens ko space, comma, ya newline se alag karo. Quotes optional hain — ignore kar diye jayenge."""
    if not update.message or update.effective_user.id != OWNER_ID: return
    global bots, BOT_TOKENS

    raw = arg(update).strip()
    if not raw:
        await update.message.reply_text(
            "❌ *Token missing!*\n\n"
            "Usage (ek token):\n`~addtoken 12345:ABCDEfgh...`\n\n"
            "Usage (multiple tokens):\n"
            "`~addtoken 12345:ABC... 67890:XYZ... 11111:QRS...`\n\n"
            "Comma bhi chal jaata hai:\n"
            "`~addtoken 12345:ABC..., 67890:XYZ...`\n\n"
            "_Ya sirf token(s) private chat mein bhejo — main khud add kar lunga._",
            parse_mode="Markdown",
        )
        return

    import re as _re
    # Strip quotes, commas, split by whitespace or commas
    cleaned   = raw.replace('"', '').replace("'", '').replace(',', ' ')
    raw_parts = cleaned.split()
    # Keep only strings that look like Telegram tokens
    candidates = [p for p in raw_parts if _re.match(r'^\d{8,10}:[A-Za-z0-9_-]{35,}$', p)]

    if not candidates:
        await update.message.reply_text(
            "❌ Koi valid token nahi mila!\n\n"
            "Token format: `12345678:ABCDEfghijklmnopqrstuvwxyz12345678`\n"
            "_Quotes aur commas ki zaroorat nahi._",
            parse_mode="Markdown",
        )
        return

    existing_dynamic = load_dynamic_tokens()
    results_ok  = []
    results_dup = []
    results_err = []

    for tok in candidates:
        if tok == HOSTING_TOKEN or tok in existing_dynamic:
            results_dup.append(tok[-10:])
            continue
        try:
            b  = Bot(tok, request=_make_request())
            me = await b.get_me()
            existing_dynamic.append(tok)
            BOT_TOKENS.append(tok)
            bots.append(b)
            results_ok.append(f"@{me.username}")
        except TelegramError as e:
            results_err.append(f"...{tok[-10:]} → `{e}`")

    save_dynamic_tokens(existing_dynamic)

    lines = [f"📊 *ADDTOKEN RESULTS* ({len(candidates)} token(s) try kiye)", ""]
    if results_ok:
        lines.append(f"✅ *Added ({len(results_ok)}):*")
        lines += [f"  • {u}" for u in results_ok]
    if results_dup:
        lines.append(f"\n⚠️ *Already exist ({len(results_dup)}):*")
        lines += [f"  • ...{t}" for t in results_dup]
    if results_err:
        lines.append(f"\n❌ *Failed ({len(results_err)}):*")
        lines += [f"  • {e}" for e in results_err]
    lines += ["", f"🤖 *Total hosted bots now: `{len(bots)}`*"]

    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def cmd_listbots(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~listbots / ~listbot — list all currently hosted bots with their usernames."""
    if not update.message or not is_auth(update.effective_user.id): return

    active_pool = pool()
    if not active_pool:
        await update.message.reply_text(
            "⚠️ <b>Koi bot loaded nahi hai abhi.</b>\n"
            "<i>Bot restart karo ya token check karo.</i>",
            parse_mode="HTML",
        )
        return

    lines = ["🤖 <b>HOSTED BOTS LIST</b>", ""]
    for i, b in enumerate(active_pool, 1):
        label = "🏠 <b>Main</b>" if i == 1 else f"➕ Extra {i - 1}"
        try:
            me = await b.get_me()
            lines.append(
                f"{i}. {label}: @{me.username}  <code>{me.id}</code>"
            )
        except Exception:
            lines.append(f"{i}. {label}: ❌ offline")

    lines += [
        "",
        f"📊 Total bots  : <code>{len(active_pool)}</code>",
        f"🟢 Known GCs   : <code>{len(known_chats)}</code>",
        f"📡 Multimode   : {'🟢 ON' if MULTIMODE else '🔴 OFF'}",
    ]
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")


async def cmd_removetoken(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~removetoken <number> — remove a bot by its index from ~listbots (can't remove main bot)."""
    if not update.message or update.effective_user.id != OWNER_ID: return
    global bots, BOT_TOKENS
    raw = arg(update).strip()
    if not raw.isdigit():
        await update.message.reply_text(
            "❌ Usage: `~removetoken <number>`\nNumber `~listbots` se dekho.",
            parse_mode="Markdown",
        )
        return
    idx = int(raw) - 1
    if idx == 0:
        await update.message.reply_text("⚠️ Main hosting bot ko remove nahi kar sakte!", parse_mode="Markdown")
        return
    if idx < 0 or idx >= len(bots):
        await update.message.reply_text(f"❌ Invalid number. Total bots: `{len(bots)}`", parse_mode="Markdown")
        return
    try:
        me = await bots[idx].get_me()
        username = f"@{me.username}"
    except Exception:
        username = "(offline bot)"
    removed_token = BOT_TOKENS[idx]
    bots.pop(idx)
    BOT_TOKENS.pop(idx)
    existing = load_dynamic_tokens()
    if removed_token in existing:
        existing.remove(removed_token)
        save_dynamic_tokens(existing)
    await update.message.reply_text(
        f"🗑️ *Bot removed!*\n{username}\n📊 Remaining bots: `{len(bots)}`",
        parse_mode="Markdown",
    )


async def cmd_multimode(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~multimode on/off/list — broadcast commands to all known GCs simultaneously."""
    if not update.message or not is_auth(update.effective_user.id): return
    global MULTIMODE
    raw = arg(update).lower().strip()

    # ── ~multimode list — show every known GC with active task status ─────────
    if raw == "list":
        if not known_chats:
            await update.message.reply_text(
                "ℹ️ *Koi known GC nahi hai abhi.*\n"
                "_Kisi group mein bot join kara pehle._",
                parse_mode="Markdown",
            )
            return
        gc_lines = []
        for i, cid in enumerate(sorted(known_chats), 1):
            active = []
            if cid in nc_tasks:       active.append("NC")
            if cid in spam_tasks:     active.append("Spam")
            if cid in crashnc_tasks:  active.append("CrashNC")
            if cid in picraid_tasks:  active.append("PicRaid")
            status = "🔴 " + "/".join(active) if active else "💤 Idle"
            gc_lines.append(f"`{i:02d}.` `{cid}` — {status}")
        gc_text = "\n".join(gc_lines)
        await update.message.reply_text(
            f"╭━━━〔 📡 MULTIMODE — GC LIST 〕━━━╮\n\n"
            f"  Total GCs  :: `{len(known_chats)}`\n"
            f"  Multimode  :: {'🟢 ON' if MULTIMODE else '🔴 OFF'}\n"
            f"  Bots       :: `{len(pool())}` active\n\n"
            f"{gc_text}\n\n"
            f"╰━━━〔 ꜱᴏᴛꜰʏ BHAGWAN CORE 〕━━━╯",
            parse_mode="Markdown",
        )
        return

    # ── No arg — show status panel ────────────────────────────────────────────
    if raw not in ("on", "off"):
        status = "🟢 ON" if MULTIMODE else "🔴 OFF"
        gc_count = len(known_chats)
        # Count how many GCs have active tasks
        active_gc = sum(
            1 for cid in known_chats
            if cid in nc_tasks or cid in spam_tasks or cid in crashnc_tasks
        )
        await update.message.reply_text(
            f"╭━━━〔 📡 MULTIMODE PANEL 〕━━━╮\n\n"
            f"  Status    :: {status}\n"
            f"  GCs       :: `{gc_count}` known  |  `{active_gc}` active\n"
            f"  Bots      :: `{len(pool())}` loaded\n\n"
            f"  `~multimode on`   — sab GCs mein broadcast\n"
            f"  `~multimode off`  — sirf current GC\n"
            f"  `~multimode list` — known GCs dekho\n\n"
            f"╰━━━〔 ꜱᴏᴛꜰʏ BHAGWAN CORE 〕━━━╯",
            parse_mode="Markdown",
        )
        return

    # ── Toggle ON / OFF ───────────────────────────────────────────────────────
    MULTIMODE = (raw == "on")
    gc_count  = len(known_chats)
    if MULTIMODE:
        # Build node-style GC status for the ON banner
        node_lines = []
        for i, cid in enumerate(sorted(known_chats), 1):
            has_task = (
                cid in nc_tasks or cid in spam_tasks or cid in crashnc_tasks
            )
            icon = "🔴" if has_task else "🟢"
            node_lines.append(f"  {icon} GC-{i:02d} :: `{cid}`")
        nodes = "\n".join(node_lines) if node_lines else "  💤 No GCs yet"
        await update.message.reply_text(
            f"╭━━━〔 📡 MULTIMODE ON 〕━━━╮\n\n"
            f"  🟢 *BROADCAST ARMED!*\n"
            f"  📡 GCs    :: `{gc_count}` targets locked\n"
            f"  🤖 Bots   :: `{len(pool())}` active\n\n"
            f"──────── TARGET NODES ────────\n"
            f"{nodes}\n"
            f"──────────────────────────────\n\n"
            f"  Ab kisi bhi GC mein command do —\n"
            f"  sab `{gc_count}` groups mein ek saath chalegi!\n\n"
            f"╰━━━〔 ꜱᴏᴛꜰʏ BHAGWAN CORE 〕━━━╯",
            parse_mode="Markdown",
        )
    else:
        await update.message.reply_text(
            f"╭━━━〔 📡 MULTIMODE OFF 〕━━━╮\n\n"
            f"  🔴 *BROADCAST DISARMED*\n"
            f"  _Commands sirf current GC mein chalenge._\n\n"
            f"╰━━━〔 ꜱᴏᴛꜰʏ BHAGWAN CORE 〕━━━╯",
            parse_mode="Markdown",
        )


async def cmd_shutdown(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~shutdown — sab bots ke sab tasks band karo (emergency stop)."""
    if not update.message or update.effective_user.id != OWNER_ID: return
    total_stopped = 0
    for cid in list(known_chats) + list(nc_tasks.keys()) + list(spam_tasks.keys()):
        stopped = cancel_all(cid)
        total_stopped += len(stopped)
    nc_tasks.clear()
    spam_tasks.clear()
    slide_tasks.clear()
    picraid_tasks.clear()
    crashnc_tasks.clear()
    crashnc2_tasks.clear()
    crashnc3_tasks.clear()
    swipe_active.clear()
    purge_chats.clear()
    react_config.clear()
    slide_target.clear()
    await update.message.reply_text(
        f"🛑 *FULL SHUTDOWN COMPLETE!*\n"
        f"⛔ Sab tasks band kiye — `{len(bots)}` bots, sab GCs\n"
        f"_Bot apne aap nahi ruka — sirf sab operations stop hue._",
        parse_mode="Markdown",
    )


async def cmd_knownchats(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~knownchats — list all known group chats."""
    if not update.message or update.effective_user.id != OWNER_ID: return
    if not known_chats:
        await update.message.reply_text("ℹ️ Koi known GC nahi hai abhi.", parse_mode="Markdown")
        return
    lines = [f"💬 *KNOWN GROUP CHATS* (`{len(known_chats)}` total)", ""]
    for i, cid in enumerate(sorted(known_chats), 1):
        active = []
        if cid in nc_tasks:    active.append("NC")
        if cid in spam_tasks:  active.append("Spam")
        if cid in picraid_tasks: active.append("PicRaid")
        status = f"⚡ {', '.join(active)}" if active else "💤 idle"
        lines.append(f"{i}. `{cid}` — {status}")
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


