async def cmd_ping(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not is_auth(update.effective_user.id): return

    import time as _time

    t_start = _time.monotonic()

    async def _ping_one(idx: int, b: Bot):
        try:
            t0 = _time.monotonic()
            me = await b.get_me()
            ms = int((_time.monotonic() - t0) * 1000)
            return f"✅ Bot {idx}: @{me.username} — `{ms}ms`", True
        except Exception as e:
            return f"❌ Bot {idx}: offline — `{e}`", False

    results = await asyncio.gather(*[_ping_one(i, b) for i, b in enumerate(bots, 1)])

    lines   = ["📡 *BOT PING STATUS*", ""]
    online  = sum(1 for _, ok in results if ok)
    offline = len(results) - online
    lines  += [line for line, _ in results]
    total_ms = int((_time.monotonic() - t_start) * 1000)
    lines   += [
        "",
        f"🟢 Online : `{online}`",
        f"🔴 Offline: `{offline}`",
        f"📊 Total  : `{len(bots)}`",
        f"⚡ Total  : `{total_ms}ms`",
    ]

    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def cmd_uptime(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~uptime — show ꜱᴏᴛꜰʏ HEALTH CORE panel with uptime, bots, memory, nodes."""
    if not update.message or not is_auth(update.effective_user.id): return

    import time as _time

    # ── Uptime ────────────────────────────────────────────────────────────────
    delta      = datetime.datetime.now() - BOT_LAUNCH_TIME
    total_secs = int(delta.total_seconds())
    days       = total_secs // 86400
    hours      = (total_secs % 86400) // 3600
    mins       = (total_secs % 3600) // 60
    secs       = total_secs % 60
    uptime_str = f"{days}d {hours}h {mins}m {secs}s"

    # ── Memory (Linux /proc, fallback to resource module) ─────────────────────
    mem_str = "N/A"
    try:
        with open("/proc/self/status") as _f:
            for _line in _f:
                if _line.startswith("VmRSS:"):
                    _kb = int(_line.split()[1])
                    mem_str = f"{_kb // 1024} MB" if _kb >= 1024 else f"{_kb} KB"
                    break
    except Exception:
        try:
            import resource as _res
            _kb = _res.getrusage(_res.RUSAGE_SELF).ru_maxrss
            # Linux = KB, macOS = bytes
            if _kb > 1_000_000:
                _kb //= 1024
            mem_str = f"{_kb // 1024} MB" if _kb >= 1024 else f"{_kb} KB"
        except Exception:
            pass

    # ── Ping every bot (parallel) ─────────────────────────────────────────────
    async def _ping_one(b: Bot):
        try:
            t0 = _time.monotonic()
            me = await b.get_me()
            ms = int((_time.monotonic() - t0) * 1000)
            return me.username, ms, True
        except Exception:
            return None, 0, False

    results = await asyncio.gather(*[_ping_one(b) for b in bots])
    online  = sum(1 for _, _, ok in results if ok)
    total_b = len(bots)
    stability = "100%" if online == total_b else f"{int(online / max(total_b, 1) * 100)}%"
    crashes   = "NONE" if online == total_b else f"{total_b - online} bot(s) down"

    # ── Build node lines ──────────────────────────────────────────────────────
    node_lines = []
    for i, (username, ms, ok) in enumerate(results, 1):
        icon  = "🟢" if ok else "🔴"
        label = f"@{username}" if username else f"bot_{i}"
        ping  = f"{ms}ms" if ok else "offline"
        node_lines.append(f"{icon} ● NODE {i:02d} :: {label}  [{ping}]")
    nodes_text = "\n".join(node_lines) if node_lines else "🔴 ● No bots loaded"

    msg = (
        "╭━━━〔 🐉 ꜱᴏᴛꜰʏ • HEALTH CORE 〕━━━╮\n"
        "\n"
        f"🟢 Status    :: ONLINE\n"
        f"🤖 Bots      :: {online}/{total_b} active\n"
        f"⏱ Uptime    :: {uptime_str}\n"
        f"💾 Memory    :: {mem_str}\n"
        "\n"
        "────────── SYSTEM NODES ──────────\n"
        f"{nodes_text}\n"
        "──────────────────────────────────\n"
        "\n"
        f"✅ Stability : {stability}\n"
        f"⚡ Crashes   : {crashes}\n"
        "\n"
        "╰━━━〔 ꜱᴏᴛꜰʏ BHAGWAN CORE 〕━━━╯"
    )
    await update.message.reply_text(msg)


async def cmd_reactloop(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """~reactloop on/off — toggle the global command-reaction emoji loop.
    When ON: har ~command pe 10 emojis ka circle chalega, phir ✅ pe settle hoga.
    Sirf OWNER toggle kar sakta hai."""
    if not update.message or update.effective_user.id != OWNER_ID: return
    global CMD_REACT_ENABLED

    raw = arg(update).lower().strip()
    if raw not in ("on", "off"):
        status = "🟢 ON" if CMD_REACT_ENABLED else "🔴 OFF"
        emojis_str = " ".join(CMD_REACT_LOOP_EMOJIS)
        await update.message.reply_text(
            f"💫 *Command Reaction Loop* : {status}\n\n"
            f"Loop emojis : `{emojis_str}`\n"
            f"Final emoji : `{CMD_REACT_FINAL_EMOJI}`\n"
            f"Step delay  : `{CMD_REACT_STEP_DELAY}s`\n\n"
            f"Usage: `~reactloop on` / `~reactloop off`",
            parse_mode="Markdown",
        )
        return

    CMD_REACT_ENABLED = (raw == "on")
    if CMD_REACT_ENABLED:
        emojis_str = " → ".join(CMD_REACT_LOOP_EMOJIS)
        await update.message.reply_text(
            f"💫 *Reaction Loop ON!*\n\n"
            f"Ab har `~command` pe yeh sequence chalega:\n"
            f"`{emojis_str} → {CMD_REACT_FINAL_EMOJI}`\n\n"
            f"_10 emojis ek ke baad ek, phir ✅ pe settle._",
            parse_mode="Markdown",
        )
    else:
        await update.message.reply_text(
            "🔴 *Reaction Loop OFF!*\n"
            "_Commands pe ab emoji loop nahi chalega._",
            parse_mode="Markdown",
        )



_WARFARE_CMDS: set[str] = {
    # NC / Rename
    "nc","fucknc","ncloop","raidnc","timenc","longnc","nc2","aninc",
    "glitchnc","glitchnc2","glitchnc3","crashnc","crashnc2","crashnc3",
    "hnc","inc","jnc","ftnc","stopftnc",
    # Spam / Raid
    "spam","spam1","crashtextraid","picraid","targetslide","Targetslide",
    # Swipe
    "swipe","stopswipe",
    # Stop
    "stopnc","stopspam","stoppicraid","stoptargetslide",
    "stopcrashnc","stopcrashnc2","stopcrashnc3","stopall",
}


def warfare_wrap(fn):
    """Decorator — handles private-chat DM routing and MULTIMODE broadcasting.

    PRIVATE CHAT behaviour (FIXED):
      - Warfare commands from DM only broadcast to all known GCs when MULTIMODE is ON.
      - If MULTIMODE is OFF and user tries from DM, they get a clear error instead of
        silently running in every GC.

    MULTIMODE behaviour:
      - When ON, after the command runs in the source GC, it is broadcast to all other
        known GCs concurrently (supports 100+ GCs via _broadcast_to_all_except).
      - When OFF, command runs ONLY in the GC where it was sent — no cross-GC leakage.
    """
    import functools

    @functools.wraps(fn)
    async def wrapper(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
        if not update.message:
            return

        chat_type = update.effective_chat.type
        txt       = (update.message.text or "").strip()

        # Parse command name and args from the raw message text
        cmd_name = ""
        raw_arg  = ""
        if txt.startswith("~"):
            parts    = txt[1:].split(None, 1)
            cmd_name = parts[0].lower()
            raw_arg  = parts[1] if len(parts) > 1 else ""

        # ── PRIVATE CHAT ───────────────────────────────────────────────────
        if chat_type == "private":
            if not is_auth(update.effective_user.id):
                return
            if cmd_name not in _WARFARE_CMDS:
                await fn(update, ctx)   # non-warfare cmd (e.g. ~status) — run normally
                return
            # MULTIMODE must be ON to broadcast from private chat
            if not MULTIMODE:
                await update.message.reply_text(
                    "⚠️ *MULTIMODE OFF hai!*\n"
                    "Private chat se command broadcast karne ke liye pehle:\n"
                    "`~multimode on` karo.\n\n"
                    "_Bina multimode ke command kisi GC mein nahi chalegi._",
                    parse_mode="Markdown",
                )
                return
            if not known_chats:
                await update.message.reply_text(
                    "⚠️ *Koi known GC nahi abhi.*\n"
                    "_Pehle kisi group mein bot ko join kara, phir yahan se command do._",
                    parse_mode="Markdown",
                )
                return
            # Broadcast to ALL known GCs concurrently
            asyncio.create_task(_broadcast_to_all_except(cmd_name, raw_arg, source_cid=None))
            gc_count = len(known_chats)
            await update.message.reply_text(
                f"📡 *DM → {gc_count} GC(s) mein broadcast!*\n"
                f"Command: `~{cmd_name}{(' ' + raw_arg) if raw_arg else ''}`\n"
                f"_Sab known groups mein concurrently execute ho raha hai._",
                parse_mode="Markdown",
            )
            return

        # ── GROUP / SUPERGROUP → normal execution ─────────────────────────
        await fn(update, ctx)

        # MULTIMODE broadcast — ONLY when explicitly ON
        if MULTIMODE and cmd_name in _WARFARE_CMDS:
            src = update.effective_chat.id
            if len(known_chats) > 1:
                asyncio.create_task(_broadcast_to_all_except(cmd_name, raw_arg, source_cid=src))

    return wrapper


