async def handle_public_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle inline button presses in the public hosting DM flow (pub: prefix)."""
    query = update.callback_query
    if not query or not query.data: return
    uid    = query.from_user.id
    action = query.data[len("pub:"):]

    await query.answer()

    if action == "start":
        _host_conv[uid] = {"step": "token"}
        kb = InlineKeyboardMarkup([[
            InlineKeyboardButton("❌ 𝗖𝗮𝗻𝗰𝗲𝗹", callback_data="pub:cancel"),
        ]])
        try:
            await query.edit_message_text(
                "╔══〔 🔑 *𝗧𝗼𝗸𝗲𝗻 𝗗𝗮𝗮𝗹𝗼* 〕══╗\n"
                "║\n"
                "║  BotFather se mila token bhejo:\n"
                "║  `123456789:ABCDefGHIjkl...`\n"
                "║\n"
                "║  _(Quotes ki zaroorat nahi)_\n"
                "╚══════════════════════╝",
                parse_mode="Markdown",
                reply_markup=kb,
            )
        except Exception:
            pass

    elif action == "cancel":
        _host_conv.pop(uid, None)
        try:
            await query.edit_message_text(
                "╔══〔 ❌ *𝗖𝗮𝗻𝗰𝗲𝗹𝗹𝗲𝗱* 〕══╗\n"
                "║  Hosting process cancel ho gayi.\n"
                "║  Dobara /start bhejo.\n"
                "╚══════════════════════╝",
                parse_mode="Markdown",
            )
        except Exception:
            pass




def _register(app: Application) -> None:
    def h(pat: str, fn):
        return MessageHandler(
            filters.Regex(rf"(?i)^~{pat}(\s|$)") & filters.TEXT, fn
        )

    def dot_h(pat: str, fn):
        return MessageHandler(
            filters.Regex(rf"(?i)^\.{pat}(\s|$)") & filters.TEXT, fn
        )

    W = warfare_wrap   # shorthand

    # ── Warfare commands — all wrapped with warfare_wrap ──────────────────────
    # warfare_wrap handles: (a) DM → broadcast to all known GCs
    #                       (b) MULTIMODE → broadcast to other known GCs after execution
    app.add_handler(h("nc",              W(cmd_nc)))
    app.add_handler(h("fucknc",          W(cmd_fucknc)))
    app.add_handler(h("ncloop",          W(cmd_ncloop)))
    app.add_handler(h("raidnc",          W(cmd_raidnc)))
    app.add_handler(h("timenc",          W(cmd_timenc)))
