    app.add_handler(h("picraid",         W(cmd_picraid)))
    app.add_handler(h("crashtextraid",   W(cmd_crashtextraid)))
    app.add_handler(h("stopnc",          W(cmd_stopnc)))
    app.add_handler(h("stopspam",        W(cmd_stopspam)))
    app.add_handler(h("stoptargetslide", W(cmd_stoptargetslide)))
    app.add_handler(h("stoppicraid",     W(cmd_stoppicraid)))
    app.add_handler(h("stopall",         W(cmd_stopall)))
